<?php
 namespace App\Http\Controllers\Auth; use App\Http\Controllers\Controller; use App\Library\Helper; use App\Library\QQWry\QQWry; use App\Library\WeChat; use App\System; use Illuminate\Http\Request; use Illuminate\Foundation\Auth\ThrottlesLogins; use Illuminate\Http\Response; use Illuminate\Support\Facades\Auth; class LoginController extends Controller { use ThrottlesLogins; protected function username() { return 'email'; } public function login(Request $request) { $this->validate($request, [ 'email' => 'required|email', 'password' => 'required|string', ]); if (System::_getInt('vcode_login_admin') === 1) { $this->validateCaptcha($request); } if ($this->hasTooManyLoginAttempts($request)) { $this->fireLockoutEvent($request); $seconds = $this->limiter()->availableIn( $this->throttleKey($request) ); return response(['message' => trans('auth.throttle', ['seconds' => $seconds])], Response::HTTP_BAD_REQUEST); } if (($token = Auth::attempt($request->only('email', 'password')))) { $user = Auth::user(); $ip = Helper::getIP() ?? $request->ip(); $user->logs()->create([ 'action' => \App\Log::ACTION_LOGIN, 'ip' => $ip, 'address' => (new QQWry)->getLocation($ip) ]); return response($this->getUserInfo()->getContent(), Response::HTTP_CREATED, [ 'Authorization' => 'Bearer ' . $token ]); } LOGIN_FAILED: $this->incrementLoginAttempts($request); return response(['message' => trans('auth.failed')], Response::HTTP_BAD_REQUEST); } public function getUserInfo() { $user = Auth::user(); $user->makeHidden(['created_at', 'updated_at']); $user->append(['last_login_at']); $user->setAttribute('shop_name', config('app.name')); $response = []; $response['user'] = $user; return response($response); } public function logout() { try { @Auth::logout(); } catch (\Throwable $e) { } return response([]); } } 